create or replace package body enrolment_api as
  function enrol(p_student_id      in number,
                 p_course_code     in varchar2,
                 p_scholarship_pct in number default 0) return number is
    l_base_fee course_enrolments.fee_due%type;
    l_fee_due number;
  begin
    insert into course_enrolments (student_id, course_code, scholarship_pct)
    values (p_student_id, p_course_code, nvl(p_scholarship_pct, 0))
    returning fee_due into l_base_fee; -- Assuming fee_due in the table is the base fee

    -- Calculate the actual fee due after applying the scholarship percentage
    l_fee_due := l_base_fee * (1 - (nvl(p_scholarship_pct, 0) / 100));

    return l_fee_due;
  end enrol;
end enrolment_api;
/
